\begin{tikzpicture}[line cap=round,line join=round,>=stealth,font=\sffamily\small]
% mirror
\draw[thick] (-2.8,0)--(2.8,0);
\foreach \x in {-2.6,-2.2,-1.8,-1.4,-1.0,-0.6,-0.2,0.2,0.6,1.0,1.4,1.8,2.2,2.6} {
  \draw[thin] (\x,0)--++(-0.15,-0.25);
}
\node[font=\footnotesize] at (2.1,-0.55) {mirror};
% normal
\draw[dashed,thick] (0,0)--(0,3.2);
\node[font=\footnotesize] at (0.55,3.0) {normal};
% incident ray
\draw[->,thick] (-2.4,2.6)--(0,0);
\node[font=\footnotesize] at (-2.55,2.85) {incident};
% reflected ray
\draw[->,thick] (0,0)--(2.4,2.6);
\node[font=\footnotesize] at (2.55,2.85) {reflected};
% angle arcs: Q (i) and R (r) from normal; P and S from mirror
\draw[thick] (0,0.7) arc (90:132:0.7);
\node at (-0.55,1.05) {Q};
\draw[thick] (0,0.7) arc (90:48:0.7);
\node at (0.55,1.05) {R};
\draw[thick] (-0.85,0) arc (180:132:0.85);
\node at (-1.25,0.45) {P};
\draw[thick] (0.85,0) arc (0:48:0.85);
\node at (1.25,0.45) {S};
\end{tikzpicture}
